"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import {
  AnchoredDocumentProvider,
  useAnchoredDocument,
  type AnchoredItem,
} from "@/components/ui/anchored-document-viewer"
import { usePdfAnchoredTarget } from "@/components/ui/pdf-anchor-target"
import {
  PdfViewerPages,
  PdfViewerProvider,
  type PdfDocumentSource,
  type PdfViewerHandle,
} from "@/components/ui/pdf-viewer"
import {
  ViewerBody,
  ViewerSurface,
  ViewerHeader,
  ViewerSidebar,
  ViewerRoot,
  ViewerSidebarTrigger,
} from "@/components/ui/viewer"

import {
  documentAiToLayoutDocument,
  type DocumentAiDocument,
} from "./layout-blocks-document-ai"
import { documentAiToPdfBlob } from "./layout-blocks-document-ai-pdf"
import { getScrollTarget } from "./layout-blocks-geometry"
import { createLayoutItemIndex } from "./layout-blocks-index"
import { LayoutBlocksPanel } from "./layout-blocks-panel"
import type { LayoutItem } from "./layout-blocks-types"
import { LayoutOverlayLayer } from "./layout-overlay-layer"

const LOW_CONFIDENCE_THRESHOLD = 0.9
const INSPECTED_LEVELS = ["block"] as const

export function DocumentAiLayoutBlocks({
  className,
  heightClassName = "h-[680px]",
  output,
}: {
  className?: string
  heightClassName?: string
  output: DocumentAiDocument
}) {
  const layoutDocument = React.useMemo(
    () => documentAiToLayoutDocument(output),
    [output]
  )
  const index = React.useMemo(
    () =>
      createLayoutItemIndex({
        items: layoutDocument.items,
        pages: layoutDocument.pages,
      }),
    [layoutDocument.items, layoutDocument.pages]
  )
  const pdfSource = useDocumentAiPdfSource(output)
  const viewerRef = React.useRef<PdfViewerHandle>(null)
  const [lowConfidenceOnly, setLowConfidenceOnly] = React.useState(false)
  const visibleItems = React.useMemo(
    () =>
      layoutDocument.items.filter((item) => {
        if (item.level !== "block") return false
        if (!lowConfidenceOnly) return true
        return (
          item.confidence != null && item.confidence < LOW_CONFIDENCE_THRESHOLD
        )
      }),
    [layoutDocument.items, lowConfidenceOnly]
  )
  const anchoredItems = React.useMemo(
    () =>
      visibleItems.map((item): AnchoredItem => {
        const page = index.pagesByNumber.get(item.pageNumber)
        const target = page ? getScrollTarget(item, page) : null
        return {
          id: item.id,
          anchor: target
            ? {
                kind: "pdf-area",
                pageNumber: target.pageNumber,
                left: target.left,
                top: target.top,
                width: target.width,
                height: target.height,
              }
            : null,
        }
      }),
    [index.pagesByNumber, visibleItems]
  )
  const target = usePdfAnchoredTarget(viewerRef)

  return (
    <AnchoredDocumentProvider items={anchoredItems} target={target}>
      <DocumentAiLayoutBlocksContent
        className={className}
        heightClassName={heightClassName}
        index={index}
        lowConfidenceOnly={lowConfidenceOnly}
        pdfSource={pdfSource}
        setLowConfidenceOnly={setLowConfidenceOnly}
        viewerRef={viewerRef}
        visibleItems={visibleItems}
      />
    </AnchoredDocumentProvider>
  )
}

function DocumentAiLayoutBlocksContent({
  className,
  heightClassName,
  index,
  lowConfidenceOnly,
  pdfSource,
  setLowConfidenceOnly,
  viewerRef,
  visibleItems,
}: {
  className?: string
  heightClassName: string
  index: ReturnType<typeof createLayoutItemIndex>
  lowConfidenceOnly: boolean
  pdfSource: ReturnType<typeof useDocumentAiPdfSource>
  setLowConfidenceOnly: React.Dispatch<React.SetStateAction<boolean>>
  viewerRef: React.RefObject<PdfViewerHandle | null>
  visibleItems: LayoutItem[]
}) {
  const {
    activeItemId,
    activateItem,
    clearPreview,
    clearSelection,
    previewItem,
    selectedItemId,
  } = useAnchoredDocument()
  const renderPageOverlay = React.useCallback(
    ({ pageNumber, rotation }: { pageNumber: number; rotation: number }) => {
      const page = index.pagesByNumber.get(pageNumber)
      if (!page) return null

      return (
        <LayoutOverlayLayer
          interactive
          activeItemId={activeItemId}
          items={visibleItems.filter((item) => item.pageNumber === pageNumber)}
          page={page}
          rotation={rotation}
          selectedItemId={selectedItemId}
          visibleLevels={INSPECTED_LEVELS}
          onItemClick={(item) => activateItem(item.id)}
          onItemPointerEnter={(item) => previewItem(item.id)}
          onItemPointerLeave={clearPreview}
        />
      )
    },
    [
      activateItem,
      activeItemId,
      clearPreview,
      index.pagesByNumber,
      previewItem,
      selectedItemId,
      visibleItems,
    ]
  )

  return (
    <ViewerRoot
      data-layout-blocks=""
      className={cn("bg-background", heightClassName, className)}
      bare
      defaultSidebarOpen
    >
      <ViewerHeader>
        <div className="flex items-center justify-between gap-3 p-3">
          <div className="flex min-w-0 items-center gap-2">
            <ViewerSidebarTrigger className="-ml-1" />
            <div className="min-w-0">
              <div className="truncate text-sm font-medium">OCR</div>
              <div className="text-xs text-muted-foreground">
                {visibleItems.length} blocks
              </div>
            </div>
          </div>
          <label className="flex shrink-0 items-center gap-2 text-xs text-muted-foreground">
            <input
              type="checkbox"
              className="size-3.5"
              checked={lowConfidenceOnly}
              onChange={(event) =>
                setLowConfidenceOnly(event.currentTarget.checked)
              }
            />
            Low confidence
          </label>
        </div>
      </ViewerHeader>
      <ViewerBody>
        <ViewerSurface>
          {pdfSource.source ? (
            <PdfViewerProvider source={pdfSource.source}>
              <PdfViewerPages
                ref={viewerRef}
                bare
                className="h-full"
                renderPageOverlay={renderPageOverlay}
              />
            </PdfViewerProvider>
          ) : (
            <div className="grid h-full place-items-center bg-muted/20 p-6 text-sm text-muted-foreground">
              {pdfSource.error ?? "Preparing OCR pages..."}
            </div>
          )}
        </ViewerSurface>
        <ViewerSidebar
          aria-label="OCR blocks"
          side="right"
          width="320px"
          className="flex min-h-0 shrink-0 flex-col border-l bg-background"
        >
          <LayoutBlocksPanel
            activeItemId={activeItemId}
            className="min-h-0 flex-1"
            emptyLabel={
              lowConfidenceOnly
                ? "No low-confidence OCR blocks found."
                : "No OCR blocks found."
            }
            items={visibleItems}
            selectedItemId={selectedItemId}
            onActiveItemIdChange={previewItem}
            onSelectedItemIdChange={(itemId) => {
              if (itemId) {
                activateItem(itemId)
                return
              }
              clearSelection()
            }}
          />
        </ViewerSidebar>
      </ViewerBody>
    </ViewerRoot>
  )
}

function useDocumentAiPdfSource(output: DocumentAiDocument) {
  const [state, setState] = React.useState<{
    error?: string
    source?: PdfDocumentSource
  }>({})

  React.useEffect(() => {
    let isCurrent = true
    setState({})

    documentAiToPdfBlob(output)
      .then((blob) => {
        if (!isCurrent) return
        setState({
          source: {
            kind: "blob",
            blob,
            fileName: "ocr-pages.pdf",
            identityKey: `document-ai-pdf:${output.pages?.length ?? 0}:${blob.size}`,
            mimeType: "application/pdf",
          },
        })
      })
      .catch((error: unknown) => {
        if (!isCurrent) return
        setState({
          error:
            error instanceof Error
              ? error.message
              : "Failed to prepare OCR pages.",
        })
      })

    return () => {
      isCurrent = false
    }
  }, [output])

  return state
}

export type { LayoutItem, LayoutLevel, LayoutPage } from "./layout-blocks-types"
export type { DocumentAiDocument } from "./layout-blocks-document-ai"
export { documentAiToLayoutDocument } from "./layout-blocks-document-ai"
export { documentAiToPdfBlob } from "./layout-blocks-document-ai-pdf"
export { createLayoutItemIndex } from "./layout-blocks-index"
export { LayoutBlocksPanel } from "./layout-blocks-panel"
export { LayoutOverlayLayer } from "./layout-overlay-layer"

import { normalizeLayoutQuad, quadToRect } from "./layout-blocks-geometry"
import type {
  LayoutDocument,
  LayoutItem,
  LayoutKind,
  LayoutLevel,
  LayoutPage,
  LayoutPoint,
  LayoutQuad,
  LayoutTextSpan,
} from "./layout-blocks-types"

type DocumentAiTextSegment = {
  startIndex?: string
  endIndex?: string
}

type DocumentAiLayout = {
  textAnchor?: {
    textSegments?: DocumentAiTextSegment[]
  }
  confidence?: number
  boundingPoly?: {
    vertices?: Array<{ x?: number; y?: number }>
    normalizedVertices?: Array<{ x?: number; y?: number }>
  }
  orientation?: number
}

type DocumentAiLayoutNode = {
  layout?: DocumentAiLayout
}

type DocumentAiPage = {
  pageNumber?: number
  dimension?: {
    width?: number
    height?: number
    unit?: string
  }
  image?: {
    content?: string
    mimeType?: string
    width?: number
    height?: number
  }
  layout?: DocumentAiLayout
  blocks?: DocumentAiLayoutNode[]
  paragraphs?: DocumentAiLayoutNode[]
  lines?: DocumentAiLayoutNode[]
  tokens?: DocumentAiLayoutNode[]
}

export type DocumentAiDocument = {
  text?: string
  pages?: DocumentAiPage[]
  mimeType?: string
  uri?: string
}

export function documentAiToLayoutDocument(
  input: DocumentAiDocument
): LayoutDocument {
  const text = input.text ?? ""
  const pages = (input.pages ?? []).flatMap((page, pageIndex) =>
    documentAiPageToLayoutPage(page, pageIndex)
  )
  const pagesByNumber = new Map(pages.map((page) => [page.pageNumber, page]))
  const items = (input.pages ?? []).flatMap((page, pageIndex) => {
    const pageNumber = page.pageNumber ?? pageIndex + 1
    const layoutPage = pagesByNumber.get(pageNumber)
    if (!layoutPage) return []

    const pageItems = [
      ...documentAiNodesToLayoutItems({
        nodes: page.blocks ?? [],
        level: "block",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.paragraphs ?? [],
        level: "paragraph",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.lines ?? [],
        level: "line",
        page: layoutPage,
        text,
      }),
      ...documentAiNodesToLayoutItems({
        nodes: page.tokens ?? [],
        level: "word",
        page: layoutPage,
        text,
      }),
    ]

    return assignDocumentAiParents(pageItems)
  })

  return { text, pages, items }
}

export function documentAiPageToDataUrl(page: DocumentAiPage) {
  if (!page.image?.content) return undefined
  return `data:${page.image.mimeType ?? "image/png"};base64,${
    page.image.content
  }`
}

function documentAiPageToLayoutPage(
  page: DocumentAiPage,
  pageIndex: number
): LayoutPage[] {
  const pageNumber = page.pageNumber ?? pageIndex + 1
  const width = finitePositiveNumber(page.dimension?.width ?? page.image?.width)
  const height = finitePositiveNumber(
    page.dimension?.height ?? page.image?.height
  )

  if (!width || !height) return []

  return [
    {
      pageNumber,
      width,
      height,
      rotation: documentAiOrientationToRotation(page.layout?.orientation),
    },
  ]
}

function documentAiNodesToLayoutItems({
  nodes,
  level,
  page,
  text,
}: {
  nodes: DocumentAiLayoutNode[]
  level: LayoutLevel
  page: LayoutPage
  text: string
}): LayoutItem[] {
  return nodes.flatMap((node, index) => {
    const layout = node.layout
    if (!layout) return []

    const span = documentAiTextSpan(layout, text.length)
    const nodeText = span ? text.slice(span.start, span.end) : ""
    const quad = documentAiLayoutQuad(layout, page)
    const normalizedQuad = normalizeLayoutQuad(quad, page)
    if (!normalizedQuad) return []

    return {
      id: documentAiLayoutItemId({ page, level, index, span }),
      pageNumber: page.pageNumber,
      level,
      kind: documentAiLayoutKind(level, nodeText),
      text: nodeText,
      confidence: normalizeConfidence(layout.confidence),
      quad: normalizedQuad,
      rect: quadToRect(normalizedQuad),
      span,
    }
  })
}

function documentAiTextSpan(
  layout: DocumentAiLayout,
  textLength: number
): LayoutTextSpan | undefined {
  const segments = layout.textAnchor?.textSegments ?? []
  if (!segments.length) return undefined

  let start = textLength
  let end = 0
  for (const segment of segments) {
    const segmentStart = parseTextIndex(segment.startIndex, 0)
    const segmentEnd = parseTextIndex(segment.endIndex, segmentStart)
    start = Math.min(start, segmentStart)
    end = Math.max(end, segmentEnd)
  }

  start = clampTextIndex(start, textLength)
  end = clampTextIndex(end, textLength)

  return end >= start ? { start, end } : undefined
}

function parseTextIndex(value: string | undefined, fallback: number) {
  if (value == null) return fallback
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : fallback
}

function clampTextIndex(value: number, textLength: number) {
  return Math.min(textLength, Math.max(0, Math.trunc(value)))
}

function documentAiLayoutQuad(
  layout: DocumentAiLayout,
  page: LayoutPage
): LayoutQuad | undefined {
  const vertices = layout.boundingPoly?.vertices
  if (vertices && vertices.length >= 4) {
    return vertices.slice(0, 4).map((vertex) => ({
      x: vertex.x ?? 0,
      y: vertex.y ?? 0,
    })) as LayoutQuad
  }

  const normalizedVertices = layout.boundingPoly?.normalizedVertices
  if (normalizedVertices && normalizedVertices.length >= 4) {
    return normalizedVertices.slice(0, 4).map((vertex) => ({
      x: (vertex.x ?? 0) * page.width,
      y: (vertex.y ?? 0) * page.height,
    })) as LayoutQuad
  }
}

function documentAiLayoutItemId({
  page,
  level,
  index,
  span,
}: {
  page: LayoutPage
  level: LayoutLevel
  index: number
  span?: LayoutTextSpan
}) {
  const spanKey = span ? `${span.start}-${span.end}` : "no-span"
  return `document-ai:p${page.pageNumber}:${level}:${index}:${spanKey}`
}

function documentAiLayoutKind(level: LayoutLevel, text: string): LayoutKind {
  const trimmedText = text.trim()
  if (/^\d+$/.test(trimmedText)) return "pageNumber"
  if (level === "paragraph" || level === "block") return "paragraph"
  return "other"
}

function documentAiOrientationToRotation(
  orientation: number | undefined
): 0 | 90 | 180 | 270 {
  switch (orientation) {
    case 2:
      return 90
    case 3:
      return 180
    case 4:
      return 270
    case 1:
    default:
      return 0
  }
}

function normalizeConfidence(confidence: number | undefined) {
  if (confidence == null || !Number.isFinite(confidence)) return undefined
  return Math.min(1, Math.max(0, confidence))
}

function finitePositiveNumber(value: number | undefined) {
  if (value == null || !Number.isFinite(value)) return undefined
  return Number.isFinite(value) && value > 0 ? value : undefined
}

function assignDocumentAiParents(items: LayoutItem[]) {
  const blocks = items.filter((item) => item.level === "block")
  const paragraphs = items.filter((item) => item.level === "paragraph")
  const lines = items.filter((item) => item.level === "line")

  return items.map((item) => {
    if (item.level === "paragraph") {
      return { ...item, parentId: findSmallestContainingSpan(item, blocks)?.id }
    }
    if (item.level === "line") {
      return {
        ...item,
        parentId: findSmallestContainingSpan(item, paragraphs)?.id,
      }
    }
    if (item.level === "word") {
      return { ...item, parentId: findSmallestContainingSpan(item, lines)?.id }
    }
    return item
  })
}

function findSmallestContainingSpan(
  item: LayoutItem,
  candidates: LayoutItem[]
): LayoutItem | undefined {
  if (!item.span) return undefined
  let parent: LayoutItem | undefined
  let parentLength = Number.POSITIVE_INFINITY

  for (const candidate of candidates) {
    if (!candidate.span) continue
    if (
      candidate.span.start > item.span.start ||
      candidate.span.end < item.span.end
    ) {
      continue
    }

    const candidateLength = candidate.span.end - candidate.span.start
    if (candidateLength < parentLength) {
      parent = candidate
      parentLength = candidateLength
    }
  }

  return parent
}

import {
  documentAiPageToDataUrl,
  type DocumentAiDocument,
} from "./layout-blocks-document-ai"

type DocumentAiPage = NonNullable<DocumentAiDocument["pages"]>[number]

type PdfImagePage = {
  data: Uint8Array
  width: number
  height: number
}

const PDF_TEXT_ENCODER = new TextEncoder()
const PDF_JPEG_QUALITY = 0.92

export async function documentAiToPdfBlob(
  document: DocumentAiDocument
): Promise<Blob> {
  const pages = document.pages ?? []
  const imagePages = await Promise.all(
    pages.flatMap((page) => {
      const dataUrl = documentAiPageToDataUrl(page)
      return dataUrl ? [documentAiPageToPdfImage(page, dataUrl)] : []
    })
  )

  if (!imagePages.length) {
    throw new Error("Document AI output has no embedded page images.")
  }

  return new Blob([writePdf(imagePages)], { type: "application/pdf" })
}

async function documentAiPageToPdfImage(
  page: DocumentAiPage,
  dataUrl: string
): Promise<PdfImagePage> {
  const image = await loadImage(dataUrl)
  const width =
    positiveNumber(page.dimension?.width ?? page.image?.width) ??
    image.naturalWidth
  const height =
    positiveNumber(page.dimension?.height ?? page.image?.height) ??
    image.naturalHeight
  const canvas = document.createElement("canvas")
  canvas.width = Math.max(1, Math.round(width))
  canvas.height = Math.max(1, Math.round(height))

  const context = canvas.getContext("2d")
  if (!context) throw new Error("Canvas 2D context is unavailable.")

  context.fillStyle = "#fff"
  context.fillRect(0, 0, canvas.width, canvas.height)
  context.drawImage(image, 0, 0, canvas.width, canvas.height)

  const jpegDataUrl = canvas.toDataURL("image/jpeg", PDF_JPEG_QUALITY)
  return {
    data: dataUrlToBytes(jpegDataUrl),
    width: canvas.width,
    height: canvas.height,
  }
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const image = new Image()
    image.onload = () => resolve(image)
    image.onerror = () =>
      reject(new Error("Failed to load Document AI page image."))
    image.src = src
  })
}

function writePdf(pages: PdfImagePage[]) {
  const chunks: Uint8Array[] = []
  const offsets: number[] = [0]
  let position = 0
  let objectNumber = 1

  function write(value: string | Uint8Array) {
    const chunk =
      typeof value === "string" ? PDF_TEXT_ENCODER.encode(value) : value
    chunks.push(chunk)
    position += chunk.length
  }

  function beginObject() {
    offsets[objectNumber] = position
    write(`${objectNumber} 0 obj\n`)
    return objectNumber++
  }

  function endObject() {
    write("endobj\n")
  }

  write("%PDF-1.4\n%\xE2\xE3\xCF\xD3\n")

  const catalogObject = beginObject()
  write("<< /Type /Catalog /Pages 2 0 R >>\n")
  endObject()

  const pagesObject = beginObject()
  const firstPageObject = 3
  const pageObjectNumbers = pages.map((_, index) => firstPageObject + index * 3)
  write(
    `<< /Type /Pages /Count ${pages.length} /Kids [${pageObjectNumbers
      .map((pageObject) => `${pageObject} 0 R`)
      .join(" ")}] >>\n`
  )
  endObject()

  for (const [index, page] of pages.entries()) {
    const pageObject = beginObject()
    const imageObject = pageObject + 1
    const contentObject = pageObject + 2
    write(
      `<< /Type /Page /Parent ${pagesObject} 0 R /MediaBox [0 0 ${page.width} ${page.height}] /Resources << /XObject << /Im${index + 1} ${imageObject} 0 R >> >> /Contents ${contentObject} 0 R >>\n`
    )
    endObject()

    beginObject()
    write(
      `<< /Type /XObject /Subtype /Image /Width ${page.width} /Height ${page.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${page.data.length} >>\nstream\n`
    )
    write(page.data)
    write("\nendstream\n")
    endObject()

    const content = `q\n${page.width} 0 0 ${page.height} 0 0 cm\n/Im${index + 1} Do\nQ\n`
    beginObject()
    write(`<< /Length ${PDF_TEXT_ENCODER.encode(content).length} >>\nstream\n`)
    write(content)
    write("endstream\n")
    endObject()
  }

  const xrefOffset = position
  write(`xref\n0 ${objectNumber}\n`)
  write("0000000000 65535 f \n")
  for (let index = 1; index < objectNumber; index += 1) {
    write(`${String(offsets[index]).padStart(10, "0")} 00000 n \n`)
  }
  write(
    `trailer\n<< /Size ${objectNumber} /Root ${catalogObject} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`
  )

  const bytes = new Uint8Array(position)
  let offset = 0
  for (const chunk of chunks) {
    bytes.set(chunk, offset)
    offset += chunk.length
  }
  return bytes
}

function dataUrlToBytes(dataUrl: string) {
  const base64 = dataUrl.split(",")[1]
  if (!base64) throw new Error("Invalid image data URL.")
  const binary = atob(base64)
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index)
  }
  return bytes
}

function positiveNumber(value: number | undefined) {
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? value
    : undefined
}

import type {
  LayoutItem,
  LayoutPage,
  LayoutPoint,
  LayoutQuad,
  LayoutRect,
} from "./layout-blocks-types"

export function clampLayoutValue(value: number, min: number, max: number) {
  if (!Number.isFinite(value)) return min
  return Math.min(max, Math.max(min, value))
}

export function normalizeLayoutRect(
  rect: LayoutRect | undefined,
  page: LayoutPage
): LayoutRect | null {
  if (!rect) return null
  if (
    !Number.isFinite(rect.left) ||
    !Number.isFinite(rect.top) ||
    !Number.isFinite(rect.width) ||
    !Number.isFinite(rect.height) ||
    rect.width <= 0 ||
    rect.height <= 0 ||
    page.width <= 0 ||
    page.height <= 0
  ) {
    return null
  }

  const left = clampLayoutValue(rect.left, 0, page.width)
  const top = clampLayoutValue(rect.top, 0, page.height)
  const right = clampLayoutValue(rect.left + rect.width, 0, page.width)
  const bottom = clampLayoutValue(rect.top + rect.height, 0, page.height)
  const width = right - left
  const height = bottom - top

  return width > 0 && height > 0 ? { left, top, width, height } : null
}

export function quadToRect(quad: LayoutQuad): LayoutRect {
  const xValues = quad.map((point) => point.x)
  const yValues = quad.map((point) => point.y)
  const left = Math.min(...xValues)
  const top = Math.min(...yValues)
  const right = Math.max(...xValues)
  const bottom = Math.max(...yValues)

  return {
    left,
    top,
    width: right - left,
    height: bottom - top,
  }
}

export function rectToQuad(rect: LayoutRect): LayoutQuad {
  return [
    { x: rect.left, y: rect.top },
    { x: rect.left + rect.width, y: rect.top },
    { x: rect.left + rect.width, y: rect.top + rect.height },
    { x: rect.left, y: rect.top + rect.height },
  ]
}

export function normalizeLayoutQuad(
  quad: LayoutQuad | undefined,
  page: LayoutPage
): LayoutQuad | null {
  if (!quad || page.width <= 0 || page.height <= 0) return null
  const normalizedQuad = quad.map((point) => ({
    x: clampLayoutValue(point.x, 0, page.width),
    y: clampLayoutValue(point.y, 0, page.height),
  })) as LayoutQuad
  const rect = quadToRect(normalizedQuad)

  return rect.width > 0 && rect.height > 0 ? normalizedQuad : null
}

export function normalizeRotation(rotation: number): 0 | 90 | 180 | 270 {
  const normalized = ((rotation % 360) + 360) % 360
  if (normalized < 45 || normalized >= 315) return 0
  if (normalized < 135) return 90
  if (normalized < 225) return 180
  return 270
}

export function getRotatedPageSize(
  page: LayoutPage,
  rotation: number = page.rotation
) {
  const normalizedRotation = normalizeRotation(rotation)
  return normalizedRotation === 90 || normalizedRotation === 270
    ? { width: page.height, height: page.width }
    : { width: page.width, height: page.height }
}

export function rotatePoint(
  point: LayoutPoint,
  page: LayoutPage,
  rotation: number = page.rotation
): LayoutPoint {
  switch (normalizeRotation(rotation)) {
    case 90:
      return { x: page.height - point.y, y: point.x }
    case 180:
      return { x: page.width - point.x, y: page.height - point.y }
    case 270:
      return { x: point.y, y: page.width - point.x }
    case 0:
    default:
      return point
  }
}

export function rotateQuad(
  quad: LayoutQuad,
  page: LayoutPage,
  rotation: number = page.rotation
): LayoutQuad {
  return quad.map((point) => rotatePoint(point, page, rotation)) as LayoutQuad
}

export function itemToQuad(
  item: LayoutItem,
  page: LayoutPage
): LayoutQuad | null {
  const quad = normalizeLayoutQuad(item.quad, page)
  if (quad) return quad
  const rect = normalizeLayoutRect(item.rect, page)
  return rect ? rectToQuad(rect) : null
}

export function itemToRect(
  item: LayoutItem,
  page: LayoutPage
): LayoutRect | null {
  const quad = itemToQuad(item, page)
  return quad ? quadToRect(quad) : normalizeLayoutRect(item.rect, page)
}

export function toPercentRect(
  rect: LayoutRect,
  page: LayoutPage,
  rotation: number = page.rotation
): LayoutRect {
  const size = getRotatedPageSize(page, rotation)
  return {
    left: (rect.left / size.width) * 100,
    top: (rect.top / size.height) * 100,
    width: (rect.width / size.width) * 100,
    height: (rect.height / size.height) * 100,
  }
}

export function toSvgPoints(
  quad: LayoutQuad,
  page: LayoutPage,
  rotation: number = page.rotation
): string {
  const rotatedQuad = rotateQuad(quad, page, rotation)
  const size = getRotatedPageSize(page, rotation)

  return rotatedQuad
    .map(
      (point) =>
        `${(point.x / size.width) * 100},${(point.y / size.height) * 100}`
    )
    .join(" ")
}

export function getScrollTarget(item: LayoutItem, page: LayoutPage) {
  const rect = itemToRect(item, page)

  return {
    pageNumber: item.pageNumber,
    left: rect ? (rect.left / page.width) * 100 : 0,
    top: rect ? (rect.top / page.height) * 100 : 0,
    width: rect ? (rect.width / page.width) * 100 : 0,
    height: rect ? (rect.height / page.height) * 100 : 0,
  }
}

import type { LayoutItem, LayoutLevel, LayoutPage } from "./layout-blocks-types"

export type LayoutItemIndex = {
  itemsById: Map<string, LayoutItem>
  itemsByPage: Map<number, LayoutItem[]>
  itemsByLevel: Map<LayoutLevel, LayoutItem[]>
  pagesByNumber: Map<number, LayoutPage>
}

export function createLayoutItemIndex({
  items,
  pages,
}: {
  items: LayoutItem[]
  pages: LayoutPage[]
}): LayoutItemIndex {
  const itemsById = new Map<string, LayoutItem>()
  const itemsByPage = new Map<number, LayoutItem[]>()
  const itemsByLevel = new Map<LayoutLevel, LayoutItem[]>()
  const pagesByNumber = new Map<number, LayoutPage>()

  for (const page of pages) {
    pagesByNumber.set(page.pageNumber, page)
  }

  for (const item of items) {
    itemsById.set(item.id, item)
    appendMapValue(itemsByPage, item.pageNumber, item)
    appendMapValue(itemsByLevel, item.level, item)
  }

  return {
    itemsById,
    itemsByPage,
    itemsByLevel,
    pagesByNumber,
  }
}

function appendMapValue<Key, Value>(
  map: Map<Key, Value[]>,
  key: Key,
  value: Value
) {
  const values = map.get(key)
  if (values) {
    values.push(value)
    return
  }
  map.set(key, [value])
}

export function getLayoutItemsForPage({
  index,
  pageNumber,
  levels,
}: {
  index: LayoutItemIndex
  pageNumber: number
  levels?: readonly LayoutLevel[]
}) {
  const pageItems = index.itemsByPage.get(pageNumber) ?? []
  if (!levels?.length) return pageItems
  const levelSet = new Set(levels)
  return pageItems.filter((item) => levelSet.has(item.level))
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { itemToQuad, toSvgPoints } from "./layout-blocks-geometry"
import type { LayoutItem, LayoutLevel, LayoutPage } from "./layout-blocks-types"

const OVERLAY_BLUE = "rgb(37 99 235)"
const OVERLAY_ACTIVE_PURPLE = "rgb(147 51 234)"
const OVERLAY_ACTIVE_PURPLE_FILL = "rgb(147 51 234 / 0.12)"
const OVERLAY_STROKE_WIDTH = 1.6
const OVERLAY_ACTIVE_STROKE_WIDTH = 2.2

export function LayoutOverlayLayer({
  activeItemId,
  className,
  interactive = false,
  items,
  onItemClick,
  onItemPointerEnter,
  onItemPointerLeave,
  page,
  rotation = page.rotation,
  selectedItemId,
  visibleLevels,
}: {
  activeItemId?: string | null
  className?: string
  interactive?: boolean
  items: LayoutItem[]
  onItemClick?: (item: LayoutItem) => void
  onItemPointerEnter?: (item: LayoutItem) => void
  onItemPointerLeave?: () => void
  page: LayoutPage
  rotation?: number
  selectedItemId?: string | null
  visibleLevels?: readonly LayoutLevel[]
}) {
  const visibleLevelSet = React.useMemo(
    () => (visibleLevels?.length ? new Set(visibleLevels) : null),
    [visibleLevels]
  )
  const renderedItems = React.useMemo(
    () =>
      visibleLevelSet
        ? items.filter((item) => visibleLevelSet.has(item.level))
        : items,
    [items, visibleLevelSet]
  )

  return (
    <svg
      aria-hidden={!interactive}
      className={cn(
        "absolute inset-0 z-10 size-full",
        interactive ? "pointer-events-auto" : "pointer-events-none",
        className
      )}
      preserveAspectRatio="none"
      viewBox="0 0 100 100"
    >
      {renderedItems.map((item) => {
        const quad = itemToQuad(item, page)
        if (!quad) return null

        const isActive = item.id === activeItemId
        const isSelected = item.id === selectedItemId
        const isEmphasized = isActive || isSelected

        return (
          <polygon
            key={item.id}
            data-item-id={item.id}
            points={toSvgPoints(quad, page, rotation)}
            vectorEffect="non-scaling-stroke"
            role={interactive ? "button" : undefined}
            tabIndex={interactive ? 0 : undefined}
            aria-label={
              interactive
                ? `${item.level} ${item.text.trim() || "layout item"}`
                : undefined
            }
            className={cn(
              "transition-[fill,stroke,stroke-width]",
              interactive && "cursor-pointer outline-none",
              interactive && "focus-visible:outline-none"
            )}
            style={{
              fill: isEmphasized ? OVERLAY_ACTIVE_PURPLE_FILL : "transparent",
              stroke: isEmphasized ? OVERLAY_ACTIVE_PURPLE : OVERLAY_BLUE,
            }}
            strokeWidth={
              isEmphasized ? OVERLAY_ACTIVE_STROKE_WIDTH : OVERLAY_STROKE_WIDTH
            }
            onClick={() => onItemClick?.(item)}
            onKeyDown={(event) => {
              if (!interactive) return
              if (event.key === "Enter" || event.key === " ") {
                event.preventDefault()
                onItemClick?.(item)
              }
            }}
            onPointerEnter={() => onItemPointerEnter?.(item)}
            onPointerLeave={onItemPointerLeave}
          />
        )
      })}
    </svg>
  )
}

"use client"

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"

import { cn } from "@/lib/utils"
import { ScrollArea } from "@/components/ui/scroll-area"

import type { LayoutItem, LayoutLevel } from "./layout-blocks-types"

const ROW_ESTIMATE_SIZE = 84
const ROW_PADDING = 12

const LEVEL_LABEL: Record<LayoutLevel, string> = {
  block: "Block",
  paragraph: "Paragraph",
  line: "Line",
  word: "Word",
}

export function LayoutBlocksPanel({
  activeItemId,
  className,
  emptyLabel = "No layout items found.",
  items,
  onActiveItemIdChange,
  onNavigateItem,
  onSelectedItemIdChange,
  renderItemContent,
  selectedItemId,
}: {
  activeItemId?: string | null
  className?: string
  emptyLabel?: string
  items: LayoutItem[]
  onActiveItemIdChange?: (itemId: string | null) => void
  onNavigateItem?: (item: LayoutItem, options?: ScrollToOptions) => void
  onSelectedItemIdChange?: (itemId: string | null) => void
  renderItemContent?: (item: LayoutItem) => React.ReactNode
  selectedItemId?: string | null
}) {
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const virtualizer = useVirtualizer({
    count: items.length,
    estimateSize: () => ROW_ESTIMATE_SIZE,
    getItemKey: (index) => items[index]?.id ?? index,
    getScrollElement: () => viewportRef.current,
    overscan: 8,
  })

  return (
    <div
      data-slot="layout-blocks-panel"
      className={cn("flex min-h-0 flex-col bg-background", className)}
    >
      <ScrollArea
        className="min-h-0 flex-1"
        scrollFade
        viewportRef={viewportRef}
      >
        {items.length ? (
          <div
            role="listbox"
            aria-label="OCR blocks"
            className="relative"
            style={{
              height: virtualizer.getTotalSize() + ROW_PADDING * 2,
            }}
          >
            {virtualizer.getVirtualItems().map((virtualRow) => {
              const item = items[virtualRow.index]
              if (!item) return null

              return (
                <div
                  key={virtualRow.key}
                  ref={virtualizer.measureElement}
                  data-index={virtualRow.index}
                  className="absolute top-0 right-3 left-3 pb-2 [contain:layout_paint]"
                  style={{
                    transform: `translateY(${
                      virtualRow.start + ROW_PADDING
                    }px)`,
                  }}
                >
                  <LayoutItemRow
                    item={item}
                    isActive={item.id === activeItemId}
                    isSelected={item.id === selectedItemId}
                    renderItemContent={renderItemContent}
                    onActiveItemIdChange={onActiveItemIdChange}
                    onNavigateItem={onNavigateItem}
                    onSelectedItemIdChange={onSelectedItemIdChange}
                  />
                </div>
              )
            })}
          </div>
        ) : (
          <div className="p-3">
            <div className="rounded-lg border bg-muted/30 p-3 text-sm text-muted-foreground">
              {emptyLabel}
            </div>
          </div>
        )}
      </ScrollArea>
    </div>
  )
}

function LayoutItemRow({
  isActive,
  isSelected,
  item,
  onActiveItemIdChange,
  onNavigateItem,
  onSelectedItemIdChange,
  renderItemContent,
}: {
  isActive: boolean
  isSelected: boolean
  item: LayoutItem
  onActiveItemIdChange?: (itemId: string | null) => void
  onNavigateItem?: (item: LayoutItem, options?: ScrollToOptions) => void
  onSelectedItemIdChange?: (itemId: string | null) => void
  renderItemContent?: (item: LayoutItem) => React.ReactNode
}) {
  const confidence = item.confidence
  const confidenceLabel =
    confidence == null ? "Unknown" : `${Math.round(confidence * 100)}%`
  const text = item.text.replace(/\s+/g, " ").trim()

  function selectItem() {
    onSelectedItemIdChange?.(item.id)
    onNavigateItem?.(item, { behavior: "smooth" })
  }

  function previewItem() {
    onActiveItemIdChange?.(item.id)
    onNavigateItem?.(item, { behavior: "auto" })
  }

  return (
    <button
      type="button"
      role="option"
      aria-selected={isSelected}
      aria-current={isActive ? "true" : undefined}
      className={cn(
        "w-full rounded-lg border bg-background p-3 text-left transition-[background-color,border-color,box-shadow] outline-none hover:bg-muted/40 focus-visible:ring-2 focus-visible:ring-ring",
        isActive && "border-primary/50 bg-primary/5",
        isSelected && "border-primary bg-primary/8 shadow-sm"
      )}
      onBlur={() => onActiveItemIdChange?.(null)}
      onClick={selectItem}
      onFocus={previewItem}
      onKeyDown={(event) => {
        if (event.key === "Escape") {
          event.preventDefault()
          onActiveItemIdChange?.(null)
          if (isSelected) onSelectedItemIdChange?.(null)
        }
      }}
      onMouseEnter={previewItem}
      onMouseLeave={() => onActiveItemIdChange?.(null)}
    >
      <div className="flex min-w-0 items-center gap-2">
        <span className="rounded-md bg-muted px-1.5 py-0.5 text-[11px] font-medium text-muted-foreground">
          {LEVEL_LABEL[item.level]}
        </span>
        <span
          className={cn(
            "text-[11px] font-medium",
            confidence != null && confidence < 0.9
              ? "text-destructive"
              : "text-muted-foreground"
          )}
        >
          {confidenceLabel}
        </span>
        <span className="ml-auto text-[11px] text-muted-foreground">
          p. {item.pageNumber}
        </span>
      </div>
      <div className="mt-2 text-sm leading-5 text-foreground">
        {renderItemContent ? (
          renderItemContent(item)
        ) : (
          <span className="line-clamp-3">{text || "Empty text"}</span>
        )}
      </div>
    </button>
  )
}
